						</div>

						<div class="btn btn-xs btn-outline-secondary mt-4 " @click="$refs.patientModalFormX.open(item.id)">Editar paciente</div>
					</b-collapse>
				</div>
			</div>

			<div class="btn btn-block" v-b-toggle.clientDataCollpsed>
				<div v-if="expanded" class="icon icon-up-open-mini"></div>
				<div v-if="!expanded" class="icon icon-down-open-mini"></div>
			</div>
		</div>

		<PatientModalForm ref="patientModalFormX" @upserted="load" />
	</div>
</template>

<script>
import gql from "graphql-tag"
import PatientModalForm from "@/views/patients/PatientModalForm"

export default {
	name: "ClientForm",
	components: {
		PatientModalForm
	},
	props: {
		id: {
			required: true
		},
		minified: { default: false },
		expanded: { type: Boolean, default: false },
		canEdit: { type: Boolean, default: false }
	},
	data() {
		return {
			loading: false,
			item: null
		}
	},
	async beforeMount() {
		this.loading = true
		await this.load()
		this.loading = false
	},
	methods: {
		load() {
			return this.$apollo
				.query({
					query: gql`
						query($id: ID!) {
							patient(id: $id) {
								id
								name
								lastname
								email
								birthdate
								age
								document {
									type
									number
								}
								phone {
									countryCode
									national
									international
									type
									validated
								}
							}
						}
					`,
					variables: { id: this.id },
					fetchPolicy: "network-only"
				})
				.then(({ data }) => {
					this.item = data.patient
				})
		}
	}
}
</script>

