<template>
	<div>
		<div class="input-select" v-if="!product">
			<p>
				Busque por nombre y/o principio activo
			</p>

			<div class="search">
				<div class="search-input">
					<input type="text" @input="search" v-model="searchText" ref="searchInput" autofocus />
					<i class="icon icon-search"></i>
				</div>

				<div class="option-dropdown" v-if="amps.length > 0 || vmps.length > 0">
					<div class="option-subtitle" v-if="amps.length > 0">MEDICAMENTOS COMERCIALES</div>
					<div class="item" v-for="option in amps" :key="option.id" @click="selectAMP(option)">
						<div>
							{{ option.labName }}<br />
							<strong>{{ option.name }}</strong>
							<div class="text-secondary">
								<span v-for="(droug, i) in option.substances" :key="i">{{ droug.name }}</span>
							</div>
						</div>
					</div>

					<div class="option-subtitle" v-if="vmps.length > 0">MEDICAMENTOS GENERICOS</div>
					<div class="item" v-for="option in vmps" :key="option.VMP_Id" @click="selectVMP(option)">
						<div>
							<strong>{{ option.name }}</strong>
							<div class="text-secondary">
								<span v-for="(droug, i) in option.substances" :key="i">{{ droug.name }}</span>
							</div>
						</div>
					</div>
				</div>
			</div>
		</div>

		<div class="product-detail" v-if="product">
			<ProductCard :product="product" class="mt-2" />

			<FormulateForm ref="form" v-model="form" @submit="save">
				<div class="mt-3 dosification">
					<div class="d-flex align-items-center">
						<FormulateInput label="Indicaciones" name="dose" type="number" validation-name="Unidad" min="0" class="m-0" style="width:80px" />
						<div class="mt-3 ml-2">{{ product.dosificationUnit }}</div>
					</div>
					<small class="text-secondary mb-2">*Para fraccionar ingrese decimales. Ej: 1 comp y medio = 1.5</small>

					<FormulateInput label="cada" name="frecuency" :options="{ HOUR: 'Horas', DAYS: 'Dias', WEEK: 'Semanas' }" type="keyValue" min="0" validation-name="Frecuencia" class="m-0 mb-2" />
					<FormulateInput label="durante" name="duration" :options="{ HOUR: 'Horas', DAYS: 'Dias', WEEK: 'Semanas' }" type="keyValue" min="0" validation-name="Duración" class="m-0 mb-2" />
				</div>

				<FormulateInput class="mt-2" label="Afecciones" type="textarea" name="affections" help="(opcional)" />

				<FormulateInput class="mt-2" label="Antecedentes" type="textarea" name="medicalHistory" help="(opcional)" />

				<FormulateInput class="mt-2" label="Fecha límite para dispensar" name="expireAt" type="date" validation-name="Vencimiento" validation="required" :min="today" />

				<div class="d-flex justify-content-end mt-4">
					<FormulateInput type="button" disabled v-if="saving">Guardando <span class="loader"/></FormulateInput>
					<FormulateInput type="submit" label="Agregar" v-else />
				</div>
			</FormulateForm>
		</div>
	</div>
</template>

<script>
import gql from "graphql-tag"
import ProductCard from "@/views/products/ProductCard"
import axios from "axios"

export default {
	name: "PrescribeMedicineForm",
	components: { ProductCard },
	data() {
		return {
			searchText: "",
			loading: true,
			amps: [],
			vmps: [],
			doseOptions: [],

			product: null,
			today: this.$moment().format("YYYY-MM-DD"),
			form: {
				qty: 1,
				dose: 1,
				doseUnit: null,
				frecuency: { value: 8, option: "HOUR" },
				duration: { value: 8, option: "DAYS" },
				medicalHistory: null,
				affections: null,
				expireAt: this.$moment()
					.add(3, "month")
					.format("YYYY-MM-DD")
			}
		}
	},

	mounted() {
		// this.$refs.searchInput.$el.children[0].focus()
		this.$nextTick(() => this.$refs.searchInput.focus())
	},

	methods: {
		save() {
			console.log(this.form)
			this.$emit("created", { ...this.form, product: this.product })
		},

		async selectAMP(amp) {
			this.product = amp
			this.form.doseUnit = amp.dosificationUnit
			this.form.doseType = amp.dosificationType
		},
		async selectVMP(vmp) {
			
			this.product = vmp
			this.form.doseUnit = vmp.dosificationUnit
			this.form.doseType = vmp.dosificationType
		},

		search() {
			if (this.searchText != "") {
				this.$apollo
					.query({
						query: gql`
							query($take: Int, $skip: Int, $search: String) {
								products(take: $take, skip: $skip, search: $search) {
									data {
										id
										type
										name
										labName
										substances {
											name
											dosif
											unit
										}
										dosificationUnit
										dosificationType
									}
									pageInfo {
										totalItems
									}
								}
							}
						`,
						variables: {
							take: 10,
							skip: 0,
							search: this.searchText
						},
						fetchPolicy: "no-cache"
					})
					.then(data => {
						console.log(data)
						this.amps = data.data.products.data.filter(item => item.type == "AMP")
						this.vmps = data.data.products.data.filter(item => item.type == "VMP")

						this.loading = false
					})

			}
		}
	}
}
</script>

