<template>
	<FormulateForm v-if="!loading" ref="form" v-model="form" @submit="save">
		<FormulateInput label="Nombre" name="name" validation-name="Nombre" validation="required" />

		<FormulateInput label="Apellido" name="lastname" validation-name="Apellido" validation="required" />

		<FormulateInput type="identification" label="Documento de identidad" name="document" validation-name="Documento de identidad" validation="optional|^documentID" />

		<FormulateInput label="Sexo" name="sex" :options="{ MALE: 'Masculino', FEMALE: 'Femenino', UNKNOWN: 'Desconocido', NO_APPLY: 'No aplica' }" type="select" placeholder="Seleccione un sexo" validation-name="Sexo" validation="required" />

		<FormulateInput class="mt-2" type="date" name="birthdate" validation-name="La fecha de nacimiento" label="Fecha de nacimiento" :splitted="true" :validation="`required`" />

		<FormulateInput label="Teléfono" type="phone" name="phone" validation-name="Teléfono" validation="optional|^phone" />

		<div class="section-title mt-4 mb-2">Dirección de residencia</div>
		<div class="row row-xs">
			<div class="col-12 col-md-6 mb-2">
				<FormulateInput
					label="País"
					validation-name="País"
					v-model="form.addressCountry"
					:options="countries"
					type="selectSearch"
					option-value="id"
					option-text="name"
					placeholder="Seleccione un país"
					validation="required"
					:disabled="loadingCountries"
				/>
				<div class="formulate-input-help " v-if="loadingCountries">Cargando paises...</div>
			</div>
			<div class="col-12 col-md-6 mb-2">
				<FormulateInput label="Ciudad" name="addressCity" validation-name="Ciudad" validation="required" />
			</div>
		</div>

		<FormulateInput label="Calle número, etc..." name="addressStreet" validation-name="Ciudad" validation="required" help="Dirección (calle, número, apartamento, etc...)" />

		<FormulateInput label="Email" type="email" name="email" />

		<hr />
		<div class="d-flex justify-content-between mt-4">
			<FormulateInput type="button" data-ghost @click="$router.go(-1)">Cancelar</FormulateInput>
			<FormulateInput type="button" disabled v-if="saving">Guardando <span class="loader"/></FormulateInput>
			<FormulateInput type="submit" :label="title" v-else />
		</div>
	</FormulateForm>
</template>

<script>
import gql from "graphql-tag"
import mixins from "@/mixins/mixins"
import formMixins from "@/mixins/formMixins"

export default {
	name: "PatientForm",
	mixins: [mixins, formMixins],
	props: ["id"],
	data() {
		return {
			title: "Crear paciente",
			action: "create",
			loading: true,
			saving: false,
			loadingCountries: true,
			countries: [],
			form: {
				name: null,
				lastname: null,
				document: {
					type: "UY",
					number: null
				},
				birthdate: null,
				email: null,
				phone: null,
				sex: null,
				addressCountry: 226
			}
		}
	},

	async beforeMount() {
		await this.fetchData()
		if (this.id) {
			this.title = `Editar paciente`
			this.action = "update"
			await this.load()
		}
		this.loading = false
	},
	methods: {
		save() {
			if (!this.saving) {
				this.saving = true
				let dataInput = {
					name: this.form.name,
					lastname: this.form.lastname,
					email: this.form.email,
					document: this.form.document,
					birthdate: this.$moment(this.form.birthdate).format("YYYY-MM-DD"),
					phone: this.form.phone,
					sex: this.form.sex,
					addressCountry: this.form.addressCountry,
					addressCity: this.form.addressCity,
					addressStreet: this.form.addressStreet
				}

				if (this.action == "create") {
					this.create(dataInput)
				}
				if (this.action == "update") {
					this.update(dataInput)
				}
			}
		},

		create(data) {
			this.$apollo
				.mutate({
					mutation: gql`
						mutation($data: PatientInput!) {
							patientCreate(data: $data) {
								id
								name
								email
							}
						}
					`,
					variables: {
						data
					}
				})
				.then(({ data }) => {
					this.$toast.success("Paciente creado correctamente")
					this.$emit("created", data.patientCreate)
					this.saving = false
				})
				.catch(error => {
					this.parseGQLErrors(error)
					this.saving = false
				})
		},

		update(dataInput) {
			this.$apollo
				.mutate({
					mutation: gql`
						mutation($id: ID!, $data: PatientInput!) {
							patientUpdate(id: $id, data: $data) {
								id
								name
								email
							}
						}
					`,
					variables: {
						id: this.id,
						data: dataInput
					}
				})
				.then(({ data }) => {
					this.$toast.success("Paciente editado correctamente")
					this.$emit("updated", data.patientUpdate)
					this.saving = false
				})
				.catch(error => {
					this.errors = this.parseGQLErrors(error)
					this.saving = false
				})
		},

		load() {
			return this.$apollo
				.query({
					query: gql`
						query($id: ID!) {
							patient(id: $id) {
								id
								name
								lastname
								email
								birthdate
								document {
									type
									number
								}
								sex
								phone {
									countryCode
									national
									international
									type
									validated
								}
								address {
									country {
										id
										name
									}
									city
									street
								}
							}
						}
					`,
					variables: { id: this.id },
					fetchPolicy: "network-only"
				})
				.then(({ data }) => {
					this.form = {
						...this.$omitDeep(data.patient, "__typename"),
						addressCountry: data.patient.address && data.patient.address.country ? data.patient.address.country.id : null,
						addressCity: data.patient.address && data.patient.address.city ? data.patient.address.city : null,
						addressStreet: data.patient.address && data.patient.address.street ? data.patient.address.street : null
					}
				})
				.catch(() => {
					this.$toast.success("El item que desea editar no existe")
					// this.$router.go(-1)
				})
		},

		fetchData() {
			this.loadingCountries = true
			return this.$apollo
				.query({
					query: gql`
						query {
							countries {
								id
								iso
								name
								nativeName
								flag
							}
						}
					`,
					fetchPolicy: "network-only"
				})
				.then(({ data }) => {
					// this.countries = this.covertArrayToSelectableObject(data.countries)
					this.countries = data.countries
					this.loadingCountries = false
					this.$nextTick(() => {
						this.form.addressCountry = 226
					})
				})
				.catch(err => {
					console.log(err)
				})
		}
	}
}
</script>

